import { useState, useEffect } from "react";
import axios from "axios";
import { DataTable } from "primereact/datatable";
import { Column } from "primereact/column";
import { Toast } from "primereact/toast";

const VetHistory = () => {
  const [history, setHistory] = useState([]);
  const toast = useState(null);

  useEffect(() => {
    fetchHistory();
  }, []);

  const fetchHistory = async () => {
    try {
      const response = await axios.get("http://localhost:5000/api/appointment?status=Completed,Cancelled");
      setHistory(response.data);
    } catch (error) {
      console.error("Error fetching history:", error);
      toast.current?.show({ severity: "error", summary: "Error", detail: "Failed to fetch history" });
    }
  };

  // Format Date
  const dateTemplate = (rowData) => new Date(rowData.date).toLocaleString();

  return (
    <div className="bg-white p-6 rounded-lg shadow-md">
      <Toast ref={toast} position="bottom-right" />
      <h2 className="text-2xl font-bold mb-4">Appointment History</h2>

      <DataTable value={history} paginator rows={5} className="datatable">
        <Column field="_id" header="Appointment ID" sortable />
        <Column field="ownerName" header="Owner Name" sortable />
        <Column field="petName" header="Pet Name (Type)" body={(row) => `${row.petName} (${row.petType})`} sortable />
        <Column field="services" header="Services" body={(row) => row.services.join(", ")} />
        <Column field="date" header="Date" body={dateTemplate} sortable />
      </DataTable>
    </div>
  );
};

export default VetHistory;
